# Generated by `bun run generate:packaging 0.9.6`.
# Downloads the official per-machine MSI from the GitHub release.
$ErrorActionPreference = 'Stop'

if (-not [Environment]::Is64BitOperatingSystem) {
  throw 'Typsastra requires a 64-bit version of Windows.'
}

$isArm64 = $env:PROCESSOR_ARCHITECTURE -eq 'ARM64' -or $env:PROCESSOR_ARCHITEW6432 -eq 'ARM64'
$url = if ($isArm64) { 'https://github.com/Sovichea/typsastra/releases/download/v0.9.6/Typsastra_0.9.6_arm64_en-US.msi' } else { 'https://github.com/Sovichea/typsastra/releases/download/v0.9.6/Typsastra_0.9.6_x64_en-US.msi' }
$checksum = if ($isArm64) { 'be2b637562765a903c7cf3ede26bfe3afff94da4f30a206ecb23f43cc6f9aedd' } else { '89a09bb1bd121c1ab9479e1e577b6c360243934a91afc1da33bd436f32d65a61' }

$packageArgs = @{
  packageName    = $env:ChocolateyPackageName
  fileType       = 'msi'
  url64bit       = $url
  checksum64     = $checksum
  checksumType64 = 'sha256'
  silentArgs     = '/quiet /norestart'
  validExitCodes = @(0, 3010, 1641)
  softwareName   = 'Typsastra'
}

Install-ChocolateyPackage @packageArgs
